def _allow_redirect(redirect_url: str | None) -> bool:
    """Return True if redirect_url points to one of our own post-login pages."""

    if not redirect_url:
        return False

    # Backslashes and control characters are treated inconsistently by browsers
    if "\\" in redirect_url or any(ord(c) < 32 for c in redirect_url):
        return False

    parsed = urlparse(redirect_url)
    # Only relative, same-site paths: no scheme, no host, no "//host" form
    if parsed.scheme or parsed.netloc or not redirect_url.startswith("/"):
        return False
    if redirect_url.startswith("//"):
        return False

    try:
        match = resolve(parsed.path)
    except Resolver404:
        return False

    return match.url_name in POST_LOGIN_ROUTES

